SELECT * FROM em_observation_table_registry
AND (project_id = #{projectId} OR project_id IS NULL)
ORDER BY id DESC LIMIT #{limit}

SELECT * FROM em_observation_table_registry
enabled = 1 AND is_queryable = 1 AND (project_id = #{projectId} OR project_id IS NULL) AND (instrument_id = #{instrumentId} OR instrument_id IS NULL) AND (instrument_type = #{instrumentType} OR instrument_type IS NULL) AND (metric_group = #{metricCode} OR metric_group = 'low_frequency' OR metric_group IS NULL) AND storage_mode = #{expectedStorageMode}
ORDER BY CASE WHEN project_id = #{projectId} THEN 0 ELSE 1 END, CASE WHEN instrument_id = #{instrumentId} THEN 0 ELSE 1 END, CASE WHEN instrument_type = #{instrumentType} THEN 0 ELSE 1 END, CASE WHEN metric_group = #{metricCode} THEN 0 ELSE 1 END, CASE WHEN metric_group = 'low_frequency' THEN 0 ELSE 1 END, id DESC LIMIT 1
